-- Denial Trends Crosswalk DDL & Seed Script
CREATE TABLE IF NOT EXISTS denial_trends_crosswalk (
    remittance_code VARCHAR(255) PRIMARY KEY,
    remittance_description TEXT,
    "group" VARCHAR(255),
    rcm_section VARCHAR(255)
);

-- Seed Data (277 Remittance Code Mappings)
ON CONFLICT (remittance_code) DO UPDATE SET
  remittance_description = EXCLUDED.remittance_description,
  group = EXCLUDED.group,
  rcm_section = EXCLUDED.rcm_section;
